from __future__ import annotations

import datetime as dt
import json
from pathlib import Path

import pytest
from ds.cli import ui_debug

START = dt.datetime(2026, 11, 22, 14, 2, 11, tzinfo=dt.UTC)


def write(path: Path, rows: list[dict]) -> Path:
    """Rows as the app writes them, a second apart; `session` is 3f9a1c2e unless given."""
    lines = []
    for n, row in enumerate(rows):
        time = (START + dt.timedelta(seconds=n)).isoformat(timespec="milliseconds")
        lines.append(json.dumps({"time": time, "level": "INFO", "session": "3f9a1c2e"} | row))
    path.write_text("\n".join(lines) + "\n")
    return path


TURN = [
    {"kind": "chat", "source": "user", "key": "turn-1", "text": "rank my chars", "digest": "d1"},
    {"kind": "tool", "source": "smash-agent", "name": "char_ranking", "args": '{"season":"2026-3"}', "ms": 900},
    {
        "kind": "graphql",
        "source": "startgg",
        "op": "PlayerSets",
        "variables": {"page": 2},
        "url": "https://api.start.gg/gql/alpha",
        "status": 200,
        "ms": 412,
        "rows": 15,
    },
    {
        "kind": "agent",
        "source": "smash-agent",
        "name": "turn",
        "ms": 4100,
        "steps": 1,
        "cost": 0.004,
        "reply": "Mac.\nThen Ryu.",
    },
    {"kind": "chat", "source": "agent", "text": "Mac.", "digest": "d2"},
]


def test_the_newest_session_as_a_timeline(tmp_path: Path):
    path = write(
        tmp_path / "ui.jsonl", [{"kind": "chat", "source": "note", "text": "old", "session": "aaaa1111"}, *TURN]
    )
    lines = ui_debug.report(ui_debug.read_records(path), path=path)
    assert lines[0].startswith("Session 3f9a1c2e · Nov 22 14:02-14:02 · 1 turn · 0 errors")
    assert lines[2:7] == [
        '14:02:12 user  turn-1  "rank my chars"',
        '14:02:13   tool  char_ranking  {"season":"2026-3"}  900 ms',
        "14:02:14   graphql  startgg  PlayerSets  page 2  200  412 ms  15 rows",
        "14:02:15   ai  smash-agent  turn  4100 ms  1 tool call  $0.0040",
        "14:02:16 agent  Mac.",
    ]
    assert "old" not in "\n".join(lines)


def test_errors_show_and_are_counted(tmp_path: Path):
    rows = [
        {"kind": "chat", "source": "assign", "key": "assign-1", "status": "failed", "error": "Refused: models"},
        {
            "kind": "cell",
            "source": "python",
            "name": "In [3]",
            "code": "x['wins']",
            "error": "Traceback…\nKeyError: 'wins'",
        },
        {"kind": "error", "source": "browser", "name": "TypeError: smashPress is undefined", "session": ""},
        {"kind": "chat", "source": "note", "text": "after"},
    ]
    path = write(tmp_path / "ui.jsonl", rows)
    lines = ui_debug.report(ui_debug.read_records(path), path=path)
    assert "3 errors" in lines[0]
    assert lines[2:5] == [
        "14:02:11 assign  [failed]  ERROR Refused: models",
        "14:02:12 cell  In [3]  x['wins']  ERROR KeyError: 'wins'",
        "14:02:13 ERROR  browser  TypeError: smashPress is undefined",  # no session: shown by its time
    ]


def test_one_turn_in_full(tmp_path: Path):
    after = {"kind": "chat", "source": "user", "key": "turn-2", "text": "next", "digest": "d3"}
    path = write(tmp_path / "ui.jsonl", [*TURN, after])
    lines = ui_debug.report(ui_debug.read_records(path), turn=1, path=path)
    text = "\n".join(lines)
    assert lines[0].startswith("Session 3f9a1c2e, turn-1")
    assert "    reply:\n      Mac.\n      Then Ryu." in text
    assert "text:" not in text  # a short one-line value is whole in its row
    assert '    variables:\n      {\n        "page": 2' in text
    assert "next" not in text
    assert ui_debug.report(ui_debug.read_records(path), turn=7, path=path)[0].startswith(
        "Session 3f9a1c2e has no turn-7"
    )


def test_rows_logged_again_after_a_restart_are_left_out(tmp_path: Path):
    again = [{**row, "resent": True} for row in TURN if "digest" in row]
    new = {"kind": "chat", "source": "note", "text": "new", "digest": "d9", "resent": True}
    path = write(tmp_path / "ui.jsonl", [*TURN, {"kind": "app", "name": "start", "pid": 7, "session": ""}, *again, new])
    kinds = [(record["kind"], record.get("text", "")) for record in ui_debug.read_records(path)]
    assert kinds[-2:] == [("app", ""), ("chat", "new")]
    assert len(kinds) == len(TURN) + 2


def test_older_files_are_read_first_and_a_cut_line_is_skipped(tmp_path: Path):
    write(tmp_path / "ui.1.jsonl", [{"kind": "chat", "source": "note", "text": "older"}])
    path = write(tmp_path / "ui.jsonl", [{"kind": "chat", "source": "note", "text": "newer"}])
    path.write_text(path.read_text() + '{"time": "2026-11-22T14:0')
    assert [record["text"] for record in ui_debug.read_records(path)] == ["older", "newer"]


def test_no_log_and_an_unknown_session(tmp_path: Path):
    path = tmp_path / "ui.jsonl"
    assert ui_debug.report(ui_debug.read_records(path), path=path)[0].startswith("No log yet")
    write(path, TURN)
    (line,) = ui_debug.report(ui_debug.read_records(path), session="zzzz", path=path)
    assert line.startswith("Session zzzz isn't in the log")
    assert line.endswith("In it: 3f9a1c2e")


def test_sessions_are_listed_newest_last(tmp_path: Path):
    path = write(tmp_path / "ui.jsonl", [{"kind": "chat", "source": "note", "text": "a", "session": "bbbb2222"}, *TURN])
    assert ui_debug.list_sessions(ui_debug.read_records(path)) == [
        "bbbb2222  Nov 22 14:02-14:02  0 turns · 0 errors",
        "3f9a1c2e  Nov 22 14:02-14:02  1 turn · 0 errors",
    ]


def test_since(tmp_path: Path):
    now = START + dt.timedelta(minutes=30)
    assert ui_debug.parse_since("30m", now) == START
    assert ui_debug.parse_since("2h", now) == now - dt.timedelta(hours=2)
    with pytest.raises(ValueError, match="eg 30m"):
        ui_debug.parse_since("yesterday")
    path = write(tmp_path / "ui.jsonl", TURN)
    assert len(ui_debug.read_records(path, since=START + dt.timedelta(seconds=3))) == 2
